 private static string Doc(int model=55,int number=123,string tax="12345678000195",bool production=true)
 {string xml=DfeParserTests.Document(model,tax:tax);if(number!=123){string old=DfeParserTests.Key(model,tax:tax),next=DfeParserTests.Key(model,tax:tax,number:number.ToString("D9"));xml=xml.Replace(old,next).Replace(">123</",$">{number}</").Replace($"<cDV>{old[^1]}</cDV>",$"<cDV>{next[^1]}</cDV>");}return production?xml.Replace("<tpAmb>2","<tpAmb>1"):xml;}
 private static string Ev(int model=55,bool production=true)=>production?DfeParserTests.Event(model).Replace("<tpAmb>2","<tpAmb>1"):DfeParserTests.Event(model);
 [Fact]public async Task ExportsMoreThanFiveHundredNfceAndKeepsEmissionDateFilter()
 {
  await using var h=await Harness.Create();
  var paths=new List<string>();
  for(int n=1;n<=501;n++){var path=Path.Combine(h.Root,$"nfce-{n}.xml");await File.WriteAllTextAsync(path,Doc(65,number:n));paths.Add(path);}
  foreach(var chunk in paths.Chunk(200)){var imported=await h.Archive.ImportAsync(new(chunk));Assert.DoesNotContain(imported.Rows,x=>x.Outcome==ArchiveOutcome.Invalid);}h.Db.ChangeTracker.Clear();
  var oldKey=DfeParserTests.Key(65,number:"000000502");var octoberKey=DfeParserTests.Key(65,number:"000000502",ym:"2610");
  await h.Import(Doc(65,number:502).Replace(oldKey,octoberKey).Replace($"<cDV>{oldKey[^1]}</cDV>",$"<cDV>{octoberKey[^1]}</cDV>").Replace("2026-09-10","2026-10-10"));
  var request=h.Request(ExportFormat.Folder) with{Filter=new(CompanyIds:[h.Company],Models:[DocumentModel.NFCe],From:new DateOnly(2026,9,1),To:new DateOnly(2026,9,30)),Models=EnabledDocuments.NFCe,IncludeEvents=false};
  Assert.Equal(501,(await h.Service.PreviewAsync(request)).Documents);
  var result=await h.Service.ExportAsync(request);Assert.False(result.Failed,result.Code);Assert.Equal(501,result.Written);
  Assert.Equal(501,Directory.GetFiles(result.Output!,"*.xml",SearchOption.AllDirectories).Length);
  Assert.DoesNotContain(result.Rows,x=>x.Key==octoberKey);
 }
 [Theory][InlineData(ExportFormat.Zip)][InlineData(ExportFormat.Folder)]
 public async Task AllFiveModelsExportWithOriginalBytesAndHash(ExportFormat format)
 {await using var h=await Harness.Create();var originals=new Dictionary<string,byte[]>();foreach(int model in new[]{55,57,62,65,67}){string xml=Doc(model);await h.Import(xml);originals[DfeParserTests.Key(model)]=Encoding.UTF8.GetBytes(xml);}var preview=await h.Service.PreviewAsync(h.Request(format));Assert.Equal(5,preview.Documents);var result=await h.Service.ExportAsync(h.Request(format));Assert.False(result.Failed,result.Code);Assert.Equal(5,result.Written);foreach(var row in result.Rows){byte[] data=await Read(result,row.Path,format);Assert.Equal(originals[row.Key],data);Assert.Equal(row.Hash,Convert.ToHexString(SHA256.HashData(data)));Assert.Contains("Synthetic/Autorizados/2026/09 - Setembro/",row.Path);Assert.Contains("/Produção/",row.Path);}Assert.Equal(JobStatus.Completed,(await h.Db.ProcessingJobs.SingleAsync(x=>x.Id==result.JobId)).Status);}
