 [Fact]public async Task BootstrapMarksInterruptedExportWithoutDeletingOrPublishingArtifacts()
 {string dir=Path.Combine(Path.GetTempPath(),"wgs-export-restart-"+Guid.NewGuid().ToString("N"));Guid org=Guid.NewGuid(),job=Guid.NewGuid();var options=new FoundationOptions{Application=new(){OrganizationId=org,OrganizationName="Synthetic",DataDirectory=dir}};try{await using(var runtime=new FoundationRuntime(options)){await runtime.InitializeAsync();await using var scope=runtime.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<WgsDbContext>();db.ProcessingJobs.Add(new(){Id=job,OrganizationId=org,Kind=JobKind.Export,Status=JobStatus.Running,LastErrorCode="EXPORT_PREPARED"});await db.SaveChangesAsync();}await using(var runtime=new FoundationRuntime(options)){await runtime.InitializeAsync();await using var scope=runtime.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<WgsDbContext>();Assert.Equal("EXPORT_INTERRUPTED_REVIEW_PACKAGE",(await db.ProcessingJobs.SingleAsync()).LastErrorCode);Assert.Equal(JobStatus.Failed,(await db.ProcessingJobs.SingleAsync()).Status);Assert.False(db.Database.HasPendingModelChanges());}}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();Directory.Delete(dir,true);}}

 [Theory][InlineData(ExportFormat.Zip)][InlineData(ExportFormat.Folder)]
 public async Task UnplannedFileCanNeverBePublishedWithThePackage(ExportFormat format)
 {await using var h=await Harness.Create();await h.Import(Doc());if(format==ExportFormat.Folder){await File.WriteAllTextAsync(Path.Combine(h.Output,"arquivo-do-usuario.xml"),"PREEXISTENTE");var folder=await h.Service.ExportAsync(h.Request(format));Assert.Single(folder.Rows);Assert.Equal("PREEXISTENTE",await File.ReadAllTextAsync(Path.Combine(h.Output,"arquivo-do-usuario.xml")));return;}var progress=new Callback(p=>{if(p.Code=="EXPORT_VERIFYING"){string stage=Directory.GetFiles(h.Output).Single();using var zip=ZipFile.Open(stage,ZipArchiveMode.Update);using var writer=new StreamWriter(zip.CreateEntry("secret.pfx").Open());writer.Write("SYNTHETIC");}});var result=await h.Service.ExportAsync(h.Request(format),progress);Assert.Equal("EXPORT_VERIFY_FAILED",result.Code);Assert.Null(result.Output);}
 [Theory][InlineData(ExportFormat.Zip)][InlineData(ExportFormat.Folder)]
 public async Task BothFormatsExcludeAllAuxiliaryFiles(ExportFormat format)
 {await using var h=await Harness.Create();await h.Import(Doc());var result=await h.Service.ExportAsync(h.Request(format));Assert.False(result.Failed,result.Code);if(format==ExportFormat.Zip){using var zip=ZipFile.OpenRead(result.Output!);Assert.All(zip.Entries,x=>Assert.EndsWith(".xml",x.FullName));}else Assert.All(Directory.GetFiles(h.Output,"*",SearchOption.AllDirectories),x=>Assert.Equal(".xml",Path.GetExtension(x)));}
 private static async Task<byte[]> Read(ExportResult result,string relative,ExportFormat format)
 {if(format==ExportFormat.Folder)return await File.ReadAllBytesAsync(Path.Combine(result.Output!,relative));using var zip=ZipFile.OpenRead(result.Output!);using var input=zip.GetEntry(relative)!.Open();using var output=new MemoryStream();await input.CopyToAsync(output);return output.ToArray();}
 private sealed class Callback(Action<ExportProgress> callback):IProgress<ExportProgress>{public void Report(ExportProgress value)=>callback(value);}
 private sealed class Harness:IAsyncDisposable
 {
  public string Root{get;}=Path.Combine(Path.GetTempPath(),"wgs-export-"+Guid.NewGuid().ToString("N"));public string Data=>Path.Combine(Root,"data");public string Output=>Path.Combine(Root,"out");public Guid Org{get;}=Guid.NewGuid();public Guid Company{get;private set;}public WgsDbContext Db{get;private set;}=null!;public ArchiveService Archive{get;private set;}=null!;public ExportService Service{get;private set;}=null!;private readonly ArchiveGate gate=new();private readonly ExportGate exportGate=new();
  public static async Task<Harness> Create(bool twoCompanies=false,ExportLimits? limits=null)
  {var h=new Harness();Directory.CreateDirectory(h.Data);Directory.CreateDirectory(h.Output);h.Db=DatabaseFactory.Create(Path.Combine(h.Data,"db.sqlite"),h.Org);await h.Db.Database.MigrateAsync();h.Db.Organizations.Add(new(){Id=h.Org,Name="Synthetic"});var c=new Company{OrganizationId=h.Org,Cnpj="12345678000195",LegalName="Synthetic",State="SC"};h.Company=c.Id;h.Db.Companies.Add(c);if(twoCompanies)h.Db.Companies.Add(new(){OrganizationId=h.Org,Cnpj="12345678000276",LegalName="Recipient",State="SC"});await h.Db.SaveChangesAsync();var parser=new DfeParser();var location=new ArchiveLocation(h.Data,h.Org);var store=new ArchiveFileStore(location);h.Archive=new(h.Db,parser,store,h.gate);h.Service=new(h.Db,h.Archive,store,h.gate,h.exportGate,limits??new(),parser,location,TimeProvider.System);return h;}
  public async Task Import(string xml){string f=Path.Combine(Root,Guid.NewGuid().ToString("N")+".xml");await File.WriteAllTextAsync(f,xml);var result=await Archive.ImportAsync(new([f]));Assert.DoesNotContain(result.Rows,x=>x.Outcome==ArchiveOutcome.Invalid);Db.ChangeTracker.Clear();}
  public ExportRequest Request(ExportFormat format=ExportFormat.Zip)=>new(new(),Output,format);
  public async ValueTask DisposeAsync(){await Db.DisposeAsync();gate.Dispose();exportGate.Dispose();Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();Directory.Delete(Root,true);}
 }
}

